Use a small in-memory cache with a one-hour TTL. It adds no dependencies and helps stay within the API quota.

```js
// cache.js
const cache = new Map();
const TTL = 60 * 60 * 1000; // 1 hour

export function getCached(key) {
  const entry = cache.get(key);

  if (!entry || Date.now() - entry.timestamp > TTL) {
    cache.delete(key);
    return null;
  }

  return entry.data;
}

export function setCached(key, data) {
  cache.set(key, { data, timestamp: Date.now() });
}
```

Use it around your weather request:

```js
import { getCached, setCached } from "./cache.js";

export async function fetchWeather(city) {
  const key = city.trim().toLowerCase();
  const cached = getCached(key);

  if (cached) return cached;

  const response = await fetch(
    `/api/weather?city=${encodeURIComponent(city)}`
  );

  if (!response.ok) {
    throw new Error(`Weather request failed: HTTP ${response.status}`);
  }

  const data = await response.json();
  setCached(key, data);
  return data;
}
```

For autocomplete, keep the existing lightweight LRU cache: maximum 100 entries with a 5-minute TTL. Since in-memory data disappears on reload, use `localStorage` only for the last three searched cities, as your app already does.
